#!/usr/bin/env python3
"""
法律服务应标核查

**投标失败最常见的原因不是方案不好，是废标。**

方案写得再漂亮，资质缺一项、格式错一处、报价超上限，连评分环节都进不去。
所以本脚本先查废标，再谈得分。

两类内容：
  1. **废标风险核查** —— 一票否决项，缺一项即出局
  2. **评分点对照** —— 常见评分维度与应对，用于分配写作精力

⚠️ **招标文件是唯一准据。** 本清单是通用项，具体项目的废标条款、
   格式要求、资质门槛**必须逐条核对招标文件原文**——
   不同项目差异很大，通用清单只用于查漏，不能替代读文件。

用法：
    bid_check.py --type 常年顾问 --check 营业执照 律所执业许可证 法定代表人授权书
    bid_check.py --list
"""
import argparse, json, sys

# 废标项：一票否决。按出错频率排序
DISQUALIFY = [
    ("投标人资格", [
        "律师事务所执业许可证（在有效期内）",
        "营业执照或统一社会信用代码证",
        "**招标文件要求的特定资质**（如证券法律业务资格、破产管理人名册）",
        "近三年无重大违法记录声明",
        "**不在失信被执行人、重大税收违法名单内**",
    ], "资格不符是最硬的废标项，且**无法事后补正**"),
    ("投标文件形式", [
        "**按招标文件规定的格式与顺序编制**",
        "正副本份数、密封与标识符合要求",
        "**法定代表人签字与单位盖章齐全**（漏盖章是高频废标原因）",
        "法定代表人授权委托书（授权人签字、被授权人身份证明）",
        "投标文件签署页、骑缝章",
    ], "格式问题占废标的很大比例，**且多数是可避免的低级错误**"),
    ("实质性响应", [
        "**对招标文件的实质性条款无偏离**（服务范围、期限、责任）",
        "**未对招标文件提出保留或附加条件**",
        "承诺函、响应表逐项填写且无空项",
        "服务期限、响应时间符合要求",
    ], "**「实质性偏离」是废标的常见理由**——对某条不能接受的，要在答疑阶段提出，不要在投标文件中改"),
    ("报价", [
        "**不超过最高限价**",
        "报价唯一（无选择性报价、无多个报价）",
        "报价表格式与计算无误、大小写一致",
        "**不低于成本价**（明显低价可能被认定为低于成本竞标）",
    ], "报价超限价直接废标；**大小写不一致时通常以大写为准**，须核对"),
    ("时间与送达", [
        "**在投标截止时间前送达指定地点**",
        "电子标书按规定平台与格式上传并成功",
        "保证金（如有）按时足额到账",
    ], "**逾期送达一律拒收**，没有例外。电子标书要留足上传时间"),
]

# 常见评分维度
SCORING = [
    ("服务方案", "占分通常最高", [
        "**针对性** —— 是否针对本项目的实际情况，而非通用模板",
        "工作流程与阶段划分是否清晰可执行",
        "**风险识别与应对** —— 体现对招标人所处行业的理解",
        "服务标准与响应时限的具体承诺",
    ]),
    ("团队配置", "分值高且易拉开差距", [
        "**拟投入人员的执业年限、专业领域、本类项目经验**",
        "团队稳定性与备份机制",
        "**项目负责人的时间投入承诺**（招标人最关心的是「谁真正做事」）",
        "人员证书与业绩证明材料",
    ]),
    ("类似业绩", "客观分，无法临时补", [
        "近三年同类项目业绩，附合同关键页或中标通知书",
        "**业绩的相关性比数量更重要**",
        "涉及案例的**必须脱敏**",
    ]),
    ("律所综合实力", "客观分", [
        "律所规模、执业年限、专业领域",
        "行业排名、荣誉资质",
        "质量管理与保密制度",
    ]),
    ("报价", "通常为价格分", [
        "**不是越低越好** —— 明显低价可能被质疑履约能力，也可能被认定低于成本",
        "报价结构清晰，与服务范围对应",
    ]),
]

TYPES = {
    "常年顾问": ["服务范围与频次的界定", "响应时限承诺", "**不包含事项**", "增值服务"],
    "专项诉讼": ["案件分析深度", "诉讼策略", "团队诉讼经验", "风险代理安排（如允许）"],
    "并购尽调": ["尽调清单的完整性", "项目管理与时间表", "多专业协同", "保密安排"],
    "IPO法律服务": ["证券法律业务资格", "同类项目业绩", "团队配置与投入", "工作计划与申报节点"],
    "破产管理人": ["管理人名册资格", "团队与场地", "工作方案", "报酬方案"],
}


def main():
    p = argparse.ArgumentParser(description="法律服务应标核查",
                                formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--type", dest="bid_type", help=f"项目类型：{list(TYPES)}")
    p.add_argument("--check", nargs="*", default=[], help="已准备的材料，用于粗查缺漏")
    p.add_argument("--max-price", dest="max_price", type=float, help="最高限价")
    p.add_argument("--our-price", dest="our_price", type=float, help="我方报价")
    p.add_argument("--list", action="store_true")
    args = p.parse_args()

    if args.list:
        print(json.dumps({"废标项": {n: items for n, items, _ in DISQUALIFY},
                          "评分维度": {n: pts for n, _, pts in SCORING},
                          "项目类型": TYPES}, ensure_ascii=False, indent=2))
        return

    prepared = " ".join(args.check)
    dq = []
    for name, items, note in DISQUALIFY:
        rows = [{"项": it, "疑似已备": any(k in prepared for k in
                                           it.replace("**", "").split("（")[0][:6])}
                for it in items]
        dq.append({"类别": name, "要害": note, "核查项": rows,
                   "未见准备": [r["项"] for r in rows if not r["疑似已备"]]})

    price = None
    if args.max_price and args.our_price:
        over = args.our_price > args.max_price
        price = {"最高限价": args.max_price, "我方报价": args.our_price,
                 "结论": "❌ **超过限价，直接废标**" if over else "✅ 在限价内",
                 "提示": "报价**不是越低越好**——明显低价可能被质疑履约能力，"
                         "也可能被认定为低于成本竞标"}

    out = {
        "项目类型": args.bid_type or "未指定",
        "一、⚠️ 废标风险核查（一票否决）": dq,
        "二、报价核查": price or "未提供限价与报价",
        "三、评分维度与应对": [{"维度": n, "特点": w, "要点": pts} for n, w, pts in SCORING],
        "四、本类项目的特别关注": TYPES.get(args.bid_type or "", "未指定项目类型"),
        "提示": [
            "**投标失败最常见的原因不是方案不好，是废标。** "
            "方案写得再漂亮，资质缺一项、漏盖一个章，连评分环节都进不去",
            "⚠️ **招标文件是唯一准据。** 本清单是通用项，"
            "具体项目的废标条款、格式要求、资质门槛**必须逐条核对招标文件原文**",
            "**对招标文件条款有异议的，在答疑阶段提出**——"
            "在投标文件中擅自修改会构成实质性偏离而废标",
            "**方案的针对性是拉开差距的关键。** 通用模板一眼就能看出来，"
            "评委每天看几十份，针对本项目的具体分析才有印象分",
            "**类似业绩无法临时补**，但可以选择呈现方式——相关性比数量重要。"
            "涉及案例的**必须脱敏**（转「文件脱敏」）",
            "**不承诺结果。** 标书中不得出现「确保胜诉」「保证过会」这类表述——"
            "既不专业，也可能构成违规承诺",
        ],
    }
    print(json.dumps(out, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
